type fakeMailer struct {
	version   string
	changelog string
	tagName   string
	err       error
}

func (f *fakeMailer) Notify(_ context.Context, version, changelog, tagName string) error {
	f.version = version
	f.changelog = changelog
	f.tagName = tagName
	return f.err
}

func env(kv map[string]string) func(string) string {
	return func(key string) string { return kv[key] }
}

func TestRun_Success(t *testing.T) {
	fake := &fakeMailer{}
	old := newMailer
	newMailer = func(cfg plugin.EmailConfig) mailer {
		if cfg.SMTPHost != "smtp.example.com" {
			t.Fatalf("unexpected host: %s", cfg.SMTPHost)
		}
		return fake
	}
	defer func() { newMailer = old }()

	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_PLUGIN_SMTP_HOST": "smtp.example.com",
		"SEMREL_PLUGIN_FROM":      "bot@example.com",
		"SEMREL_PLUGIN_TO":        "team@example.com",
		"SEMREL_VERSION":          "v1.2.3",
		"SEMREL_CHANGELOG":        "- feature",
		"SEMREL_TAG_NAME":         "v1.2.3",
	}), &stdout, &stderr)

	if code != 0 || stderr.String() != "plugin_schema_version=1\n" {
		t.Fatalf("unexpected result: code=%d stderr=%q", code, stderr.String())
	}
	if fake.version != "v1.2.3" || fake.changelog != "- feature" || fake.tagName != "v1.2.3" {
		t.Fatalf("unexpected notify args: %+v", fake)
	}
}

func TestRun_DryRun(t *testing.T) {
	called := false
	old := newMailer
	newMailer = func(plugin.EmailConfig) mailer {
		called = true
		return &fakeMailer{}
	}
	defer func() { newMailer = old }()

	secretPass := "super-secret-smtp-password"
	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_PLUGIN_SMTP_HOST": "smtp.example.com",
		"SEMREL_PLUGIN_SMTP_PORT": "587",
		"SEMREL_PLUGIN_FROM":      "bot@example.com",
		"SEMREL_PLUGIN_TO":        "team@example.com",
		"SEMREL_PLUGIN_USERNAME":  "botuser",
		"SEMREL_PLUGIN_PASSWORD":  secretPass,
		"SEMREL_VERSION":          "v1.2.3",
		"SEMREL_CHANGELOG":        "- added dry-run support",
		"SEMREL_DRY_RUN":          "true",
	}), &stdout, &stderr)

	if code != 0 || called {
		t.Fatalf("unexpected result: code=%d called=%v", code, called)
	}
	if strings.Contains(stdout.String(), secretPass) || strings.Contains(stderr.String(), secretPass) {
		t.Fatalf("secret leaked in output: stdout=%q stderr=%q", stdout.String(), stderr.String())
	}
	if !strings.HasPrefix(stderr.String(), "plugin_schema_version=1\n") {
		t.Fatalf("missing schema version header: %q", stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-email: would send release email for v1.2.3 via smtp.example.com:587 to team@example.com (user=botuser, password=***)") {
		t.Fatalf("unexpected stderr: %q", stderr.String())
	}
	if !strings.Contains(stdout.String(), "Destination: smtp.example.com:587 (user=botuser, password=***)") ||
		!strings.Contains(stdout.String(), "Subject: [Release] v1.2.3") ||
		!strings.Contains(stdout.String(), "- added dry-run support") {
		t.Fatalf("unexpected stdout: %q", stdout.String())
	}
}

func TestRun_DryRunWithoutCredentials(t *testing.T) {
	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_VERSION": "v1.2.3",
		"SEMREL_DRY_RUN": "true",
	}), &stdout, &stderr)

	if code != 0 {
		t.Fatalf("expected exit code 0 in dry-run without credentials, got %d (stderr=%q)", code, stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-email: would need SEMREL_PLUGIN_SMTP_HOST, SEMREL_PLUGIN_FROM, SEMREL_PLUGIN_TO, SEMREL_PLUGIN_SMTP_PASSWORD to send notification") {
		t.Fatalf("expected missing credentials warning on stderr, got %q", stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-email: would send release email for v1.2.3 via <unset> to <unset>") {
		t.Fatalf("expected dry-run summary on stderr, got %q", stderr.String())
	}
	if !strings.Contains(stdout.String(), "Destination: <unset>") || !strings.Contains(stdout.String(), "Subject: [Release] v1.2.3") {
		t.Fatalf("expected rendered message on stdout, got %q", stdout.String())
	}
}

